    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = "gpt-4o-mini-2024-07-18";

// --- DI setup ---
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Information));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();
var logger = sp.GetRequiredService<ILogger<Program>>();

// --- Tools ---
var tools = new ResearchTools();
var aiTools = new List<AITool>
{
    AIFunctionFactory.Create(tools.WebSearch),
    AIFunctionFactory.Create(tools.TakeNote),
};

// --- Agent setup ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Given a topic, you must:
        1. Use the web_search tool multiple times to find relevant information.
        2. Use the take_note tool to record key findings as you go.
        3. After gathering enough information, produce a final summary of your findings.
        Be thorough but concise. Cite sources when possible.
        """,
    name: "ResearchAgent",
    description: "Researches topics by searching the web and taking notes",
    tools: aiTools,
    loggerFactory: loggerFactory,
    serviceProvider: sp);

// --- User input ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

logger.LogInformation("Researching topic: {Topic}", topic);

// --- Run agent ---
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

